import { useReducer, useCallback, useId } from 'react';

export type State = {
  activeSuggestionIndex: number | null;
  activeSuggestionElement: HTMLElement | null;
  shouldDisableSuggestions: boolean;
};

type SuggestionChangeAction = {
  type: 'suggestion-change';
  index: number;
  element: HTMLElement;
};

type UnsetSuggestionAction = {
  type: 'unset-suggestion';
};

type DisableSuggestionsAction = {
  type: 'disable-suggestions';
};

type EnableSuggestionsAction = {
  type: 'enable-suggestions';
};

type ResetSuggestionsAction = {
  type: 'reset-suggestions';
};

type Action =
  | SuggestionChangeAction
  | UnsetSuggestionAction
  | DisableSuggestionsAction
  | EnableSuggestionsAction
  | ResetSuggestionsAction;

const initialState: State = {
  activeSuggestionIndex: null,
  activeSuggestionElement: null,
  shouldDisableSuggestions: false
};

const reducer = (state: State, action: Action): State => {
  switch (action.type) {
    case 'suggestion-change':
      return {
        ...state,
        activeSuggestionIndex: action.index,
        activeSuggestionElement: action.element
      };
    case 'unset-suggestion':
      return {
        ...state,
        activeSuggestionIndex: null,
        activeSuggestionElement: null
      };
    case 'disable-suggestions':
      return {
        ...state,
        shouldDisableSuggestions: true
      };
    case 'enable-suggestions':
      return {
        ...state,
        shouldDisableSuggestions: false
      };
    case 'reset-suggestions':
      return initialState;
    default:
      return state;
  }
};

const useAutosuggestState = () => {
  const [state, dispatch] = useReducer(reducer, initialState);
  const activeSuggestionId = useId();

  const setActiveSuggestion = (params: {
    index: number;
    element: HTMLElement;
  }) => {
    dispatch({
      type: 'suggestion-change',
      ...params
    });
  };

  const unsetActiveSuggestion = () => {
    dispatch({
      type: 'unset-suggestion'
    });
  };

  const disableSuggestions = () => {
    dispatch({ type: 'disable-suggestions' });
  };

  const enableSuggestions = () => {
    dispatch({ type: 'enable-suggestions' });
  };

  const resetSuggestions = useCallback(() => {
    dispatch({ type: 'reset-suggestions' });
  }, []);

  return {
    state,
    activeSuggestionId,
    setActiveSuggestion,
    unsetActiveSuggestion,
    disableSuggestions,
    enableSuggestions,
    resetSuggestions
  };
};

export default useAutosuggestState;
